-- ==============================================================
-- ⚠️ โค้ดสร้างฐานข้อมูลแบบ CLEAN SLATE (ลบของเก่าแล้วสร้างใหม่ทั้งหมด)
-- ==============================================================

-- 1. ลบตารางเก่าทิ้งให้หมด (ถ้ามี)
DROP TABLE IF EXISTS payments CASCADE;
DROP TABLE IF EXISTS events CASCADE;
DROP TABLE IF EXISTS incomes CASCADE;
DROP TABLE IF EXISTS expenses CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- 2. สร้างตารางใหม่ทั้งหมดแบบสมบูรณ์ 100%
CREATE TABLE users (
  email text primary key,
  name text,
  student_id text,
  role text default 'Student'
);

CREATE TABLE events (
  id uuid default gen_random_uuid() primary key,
  title text not null,
  base_amount numeric not null,
  due_date date,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

CREATE TABLE payments (
  id uuid default gen_random_uuid() primary key,
  event_id uuid references events(id) on delete cascade,
  event_title text,
  student_email text references users(email) on delete cascade,
  student_name text,
  paid_amount numeric,
  penalty numeric default 0,
  status text default 'Pending',
  slip_url text,
  paid_at timestamp with time zone default timezone('utc'::text, now())
);

CREATE TABLE incomes (
  id uuid default gen_random_uuid() primary key,
  source text not null,
  amount numeric not null,
  date date,
  receipt_url text,
  added_by text,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

CREATE TABLE expenses (
  id uuid default gen_random_uuid() primary key,
  title text not null,
  amount numeric not null,
  date date,
  receipt_url text,
  added_by text,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- ปิด RLS เพื่อให้ใช้งานได้ง่ายที่สุด (เหมือน Firebase กฎเปิด)
ALTER TABLE users DISABLE ROW LEVEL SECURITY;
ALTER TABLE events DISABLE ROW LEVEL SECURITY;
ALTER TABLE payments DISABLE ROW LEVEL SECURITY;
ALTER TABLE incomes DISABLE ROW LEVEL SECURITY;
ALTER TABLE expenses DISABLE ROW LEVEL SECURITY;

